const { getLog, resetLog } = require('./src/audit');
const { db } = require('./src/db');
const ops = {
  deleteUser: [require('./src/ops/deleteUser').deleteUser, db.users, 'delete'],
  refundOrder: [require('./src/ops/refundOrder').refundOrder, db.orders, 'refund'],
  banAccount: [require('./src/ops/banAccount').banAccount, db.users, 'ban'],
  resetPassword: [require('./src/ops/resetPassword').resetPassword, db.users, 'resetPassword'],
  revokeToken: [require('./src/ops/revokeToken').revokeToken, db.tokens, 'revoke'],
  deleteFile: [require('./src/ops/deleteFile').deleteFile, db.files, 'delete'],
};
let ok = true;
for (const [name, [fn, obj, method]] of Object.entries(ops)) {
  // success path: exactly one entry, correct fields
  resetLog();
  fn('actor1', 'target1');
  const log = getLog();
  const good = log.length === 1 && log[0].actor === 'actor1' && log[0].action === name && log[0].target === 'target1';
  if (!good) { ok = false; console.log('FAIL success-path', name, JSON.stringify(log)); }

  // failure path: mutation throws -> NO audit entry
  resetLog();
  const orig = obj[method];
  obj[method] = () => { throw new Error('boom'); };
  try { fn('actor1', 'target1'); ok = false; console.log('FAIL did not throw', name); } catch (e) {}
  obj[method] = orig;
  if (getLog().length !== 0) { ok = false; console.log('FAIL failure-path logged', name, JSON.stringify(getLog())); }
}
console.log(ok ? 'ALL 6 OPS: success logs once with correct fields; failed mutation logs nothing' : 'FAILURES ABOVE');
"
